/* ---------------------------------------------------------------------------
 * 常量
 * ------------------------------------------------------------------------- */

/** 逻辑帧长（毫秒）。20 帧/秒。 */
const TICK_MS = 50;

/** 一局多少逻辑帧（1200 帧 = 60 秒）。 */
const ROUND_FRAMES = 1200;

/** 虚拟坐标系：100 × 100，y 向下。轨迹坐标也用这套，跟屏幕分辨率无关。 */
const VW = 100;
const VH = 100;

/** 物体类型。 */
const T_FRUIT = 'fruit';
const T_BOMB = 'bomb';
const T_ICE = 'ice';
const T_MAGNET = 'magnet';

/** 水果品种：半径越大越好切但分少，越小越值钱。 */
const FRUIT_KINDS = [
  { name: '西瓜', r: 6.0, points: 12, color: '#e0574f', leaf: false },
  { name: '草莓', r: 3.6, points: 16, color: '#ef476f', leaf: false },
  { name: '橙子', r: 4.6, points: 9, color: '#f7931e', leaf: true },
  { name: '苹果', r: 4.2, points: 10, color: '#d7263d', leaf: true },
  { name: '葡萄', r: 2.8, points: 20, color: '#8e44ad', leaf: true },
];

/** 炸弹半径（比水果小一点，视觉上更扎眼）。 */
const BOMB_R = 3.4;
const ICE_R = 3.8;
const MAGNET_R = 4.2;

/** 切到炸弹扣多少分。 */
const BOMB_PENALTY = 25;
/** 累计几颗炸弹直接判负。 */
const MAX_BOMBS = 3;
/** 冰冻蛋得分。 */
