/** 磁铁星得分。 */
const MAGNET_POINTS = 20;
/** 冰冻持续帧数（100 帧 = 5 秒）。 */
const FREEZE_FRAMES = 100;
/** 磁铁持续帧数（80 帧 = 4 秒）。 */
const MAGNET_FRAMES = 80;
/** 冰冻时的时间倍率（越小越慢）。 */
const FREEZE_FACTOR = 0.5;
/** 磁铁时的时间倍率。 */
const MAGNET_FACTOR = 0.8;
/** 磁铁吸引半径（虚拟单位）。 */
const MAGNET_RANGE = 22;
/** 磁铁最大吸引比例。 */
const MAGNET_PULL = 0.55;
/** 刀刃宽容度：判定时半径 +BLADE，手指划得糙也能切到。 */
const BLADE = 1.0;
/** 连击倍率上限。 */
const MAX_COMBO_MULT = 4;
/** 一个物体最多能活多久（用于粗筛，冰冻时会更久，留足余量）。 */
